1	import { describe, it, expect } from 'vitest';
2	import { EditorState } from '@codemirror/state';
3	import { EditorView, ViewPlugin, ViewUpdate } from '@codemirror/view';
4	import { checkUpdateAction, UpdateAction } from '../pluginUpdateHelper';
5	import { mouseSelectingField, setMouseSelecting } from '../mouseSelecting';
6	
7	/**
8	 * Create a test plugin that captures ViewUpdate
9	 */
10	function createCapturePlugin() {
11	  let capturedUpdate: ViewUpdate | null = null;
12	  let capturedAction: UpdateAction | null = null;
13	
14	  const plugin = ViewPlugin.fromClass(
15	    class {
16	      update(update: ViewUpdate) {
17	        capturedUpdate = update;
18	        capturedAction = checkUpdateAction(update);
19	      }
20	    }
21	  );
22	
23	  return {
24	    plugin,
25	    getUpdate: () => capturedUpdate,
26	    getAction: () => capturedAction,
27	  };
28	}
29	
30	/**
31	 * Create a test EditorView with capture plugin
32	 */
33	function createTestView(doc: string) {
34	  const capture = createCapturePlugin();
35	
36	  const state = EditorState.create({
37	    doc,
38	    extensions: [mouseSelectingField, capture.plugin],
39	  });
40	
41	  const container = document.createElement('div');
42	  const view = new EditorView({ state, parent: container });
43	
44	  return { view, capture };
45	}
46	
47	describe('checkUpdateAction', () => {
48	  describe('rebuild scenarios', () => {
49	    it('should return "rebuild" when document changed (docChanged: true)', () => {
50	      const { view, capture } = createTestView('initial text');
51	
52	      // Dispatch a document change
53	      view.dispatch({
54	        changes: { from: 0, to: 12, insert: 'modified text' },
55	      });
56	
57	      const action = capture.getAction();
58	      expect(action).toBe('rebuild');
59	
60	      view.destroy();
61	    });
62	
63	    it('should return "rebuild" when drag ends (wasDragging: true, isDragging: false)', () => {
64	      const { view, capture } = createTestView('test');
65	
66	      // Start dragging
67	      view.dispatch({
68	        effects: setMouseSelecting.of(true),
69	      });
70	
71	      // End dragging - this should trigger rebuild
72	      view.dispatch({
73	        effects: setMouseSelecting.of(false),
74	      });
75	
76	      const action = capture.getAction();
77	      expect(action).toBe('rebuild');
78	
79	      view.destroy();
80	    });
81	
82	    it('should return "rebuild" when selection changed', () => {
83	      const { view, capture } = createTestView('test text');
84	
85	      // Change selection
86	      view.dispatch({
87	        selection: { anchor: 5 },
88	      });
89	
90	      const action = capture.getAction();
91	      expect(action).toBe('rebuild');
92	
93	      view.destroy();
94	    });
95	  });
96	
97	  describe('skip scenario', () => {
98	    it('should return "skip" when currently dragging (isDragging: true)', () => {
99	      const { view, capture } = createTestView('test');
100	
101	      // Start dragging
102	      view.dispatch({
103	        effects: setMouseSelecting.of(true),
104	      });
105	
106	      // Make another change while dragging (but not ending drag)
107	      view.dispatch({
108	        selection: { anchor: 2 },
109	      });
110	
111	      const action = capture.getAction();
112	      expect(action).toBe('skip');
113	
114	      view.destroy();
115	    });
116	  });
117	
118	  describe('none scenario', () => {
119	    it('should return "none" when no relevant changes occurred', () => {
120	      const { view, capture } = createTestView('test');
121	
122	      // Dispatch an empty transaction (no changes)
123	      view.dispatch({});
124	
125	      const action = capture.getAction();
126	      expect(action).toBe('none');
127	
128	      view.destroy();
129	    });
130	  });
131	});
